func TestSecretType(t *testing.T) {
	s := NewSecret("hunter22")
	forms := []string{s.String(), s.GoString(), fmt.Sprintf("%v %+v %#v %s %q %d", s, s, s, s, s, s)}
	b, _ := json.Marshal(struct{ S Secret }{s})
	txt, _ := s.MarshalText()
	forms = append(forms, string(b), string(txt), s.LogValue().String())
	for _, f := range forms {
		if strings.Contains(f, "hunter22") || !strings.Contains(f, Redacted) {
			t.Fatalf("leak or missing redaction: %q", f)
		}
	}
	if s.Reveal() != "hunter22" || s.IsZero() || !NewSecret("").IsZero() {
		t.Fatal("reveal")
	}
}

