func TestRetryPolicy(t *testing.T) {
	p := DefaultRetryPolicy()
	if p.BackoffCap(0) != 100*time.Millisecond || p.BackoffCap(1) != 200*time.Millisecond || p.BackoffCap(20) != 10*time.Second || p.BackoffCap(5000) != 10*time.Second {
		t.Fatal("caps")
	}
	p.Rand = func() float64 { return 0.25 }
	if p.Backoff(2) != 100*time.Millisecond {
		t.Fatalf("backoff %s", p.Backoff(2))
	}
	for i := 0; i < 100; i++ {
		if d := DefaultRetryPolicy().Backoff(3); d < 0 || d > 800*time.Millisecond {
			t.Fatalf("jitter out of range: %s", d)
		}
	}
	zero := RetryPolicy{MaxRetries: -1}.withDefaults()
	if zero.MaxRetries != 0 || zero.InitialBackoff != DefaultInitialBackoff || zero.Multiplier != 2 || zero.MaxRetryAfter != DefaultMaxRetryAfter {
		t.Fatalf("defaults %+v", zero)
	}
	now := time.Date(2026, 1, 1, 0, 0, 0, 0, time.UTC)
	cases := map[string]time.Duration{
		"1":                             time.Second,
		"1.5":                           1500 * time.Millisecond,
		"Thu, 01 Jan 2026 00:00:10 GMT": 10 * time.Second,
		"Wed, 31 Dec 2025 23:00:00 GMT": 0,
	}
	for in, want := range cases {
		if got, ok := ParseRetryAfter(in, now); !ok || got != want {
			t.Errorf("ParseRetryAfter(%q) = %s %v", in, got, ok)
		}
	}
	for _, bad := range []string{"", "-1", "soon", "NaN"} {
		if _, ok := ParseRetryAfter(bad, now); ok {
			t.Errorf("ParseRetryAfter(%q) should fail", bad)
		}
	}
	if d, ok := ParseRetryAfter("1e300", now); !ok || d != time.Duration(math.MaxInt64) {
		t.Fatal("huge retry-after")
	}
}

